mapper.select:
select m.title, m.sport, m.match_date, s.amount, s.settlement_status 
from team_settlement s join team_match m
on s.team_match_id = m.team_match_id 
where m.match_date = #{targetDate}
order by match_Date 
desc;

select count(*) as pending_count, coalesce(sum(amount), 0) as pending_amount
from (select s.amount from team_settlement s join team_match m
	  on s.team_match_id = m.team_match_id
	  where m.match_date = #{targetDate}
	  and s.settlement_status = '처리중');
